/**
 * Produces the "generated proposal sample" deliverable.
 *
 * Runs the application's own pipeline end to end — a real proposal row, a real
 * Claude draft, the real gates, the real renderer — and writes the result to
 * `3/sample-proposal.md` plus `3/sample-proposal.pdf`.
 *
 * This exists because the sample is the one deliverable that cannot honestly
 * be written by hand. A document typed into a markdown file and captioned
 * "generated by the application" is a claim about a system, made without
 * running it. This script makes the claim verifiable: whoever doubts it can
 * run the command.
 *
 * It COSTS REAL MONEY — one full Opus draft plus the Haiku gate passes — so it
 * is deliberately not part of `npm test`. Requires ANTHROPIC_API_KEY.
 *
 *   npm run sample
 *   npm run sample -- --keep     leave the proposal in the database
 */
import { writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { closePool, query } from "../lib/db";
import { hashPassword } from "../lib/crypto";
import { COMPLETE_INTAKE } from "../fixtures/intakes";
import { createProposal, getSections, getGaps } from "../lib/proposal/repo";
import { generateDraft } from "../lib/proposal/service";
import { buildDocumentModel, renderMarkdown } from "../lib/docgen/markdown";
import { buildProposalPdf } from "../lib/docgen/pdf";
import { newCorrelationId } from "../lib/errors";
import type { User } from "../lib/auth";

const KEEP = process.argv.includes("--keep");
const RUN = randomUUID().slice(0, 8);
const OUT = new URL("../../", import.meta.url).pathname;

async function main(): Promise<void> {
  if (!process.env.ANTHROPIC_API_KEY) {
    console.error(
      "ANTHROPIC_API_KEY is not set. This script makes real model calls — that is the point of it.\n" +
        "Set the key in build/.env.local and run again.",
    );
    process.exitCode = 1;
    return;
  }

  const password = await hashPassword(`sample-${RUN}-password`);
  const rows = await query<{ id: string }>(
    `INSERT INTO users (email, name, role, password_hash)
     VALUES ($1, $2, 'salesperson', $3) RETURNING id`,
    [`sample-${RUN}@example.invalid`, "Sample Author", password],
  );
  const authorId = rows[0]!.id;
  const actor: User = {
    id: authorId,
    email: `sample-${RUN}@example.invalid`,
    name: "Sample Author",
    role: "salesperson",
    is_active: true,
  };

  const { proposal } = await createProposal({
    authorId,
    intake: COMPLETE_INTAKE,
    idempotencyKey: `sample:${RUN}`,
  });
  console.log(`Created ${proposal.ref}. Generating — this takes a minute and costs real money.`);

  await generateDraft({
    proposalId: proposal.id,
    actor,
    correlationId: newCorrelationId(),
    onEvent: (event) => {
      if (event.type === "section_done") console.log(`  ✓ ${event.key}`);
      else if (event.type === "status") console.log(`  … ${event.message}`);
      else if (event.type === "error") console.error(`  ✗ ${event.message}`);
    },
  });

  const sections = await getSections(proposal.id);
  const gaps = await getGaps(proposal.id);
  const model = buildDocumentModel({
    ref: proposal.ref,
    intake: COMPLETE_INTAKE,
    sections: sections.map((s) => ({ key: s.key, heading: s.heading, body_md: s.body_md })),
    forClient: true,
  });

  const header = [
    "# Generated Proposal Sample",
    "",
    `Produced by running \`npm run sample\` against the deployed pipeline on ${new Date().toISOString().slice(0, 10)}.`,
    "Not written by hand: every word below the rule was drafted by Claude through the",
    "application's own generation path, passed both gates, and was rendered by the same",
    "renderer that produces the client's PDF.",
    "",
    `- **Reference:** ${proposal.ref}`,
    `- **Model:** claude-opus-5 (draft, high effort) · claude-haiku-4-5 (gap + grounding gates)`,
    `- **Gaps raised:** ${gaps.filter((g) => g.severity === "blocking").length} blocking, ${gaps.filter((g) => g.severity === "advisory").length} advisory`,
    "",
    "---",
    "",
  ].join("\n");

  await writeFile(`${OUT}sample-proposal.md`, header + renderMarkdown(model), "utf8");
  await writeFile(`${OUT}sample-proposal.pdf`, await buildProposalPdf(model));
  console.log(`\nWrote 3/sample-proposal.md and 3/sample-proposal.pdf`);

  if (!KEEP) {
    await query("DELETE FROM proposals WHERE id = $1", [proposal.id]);
    await query("DELETE FROM users WHERE id = $1", [authorId]);
    console.log("Cleaned up. Pass --keep to leave the proposal in the database.");
  }

  await closePool();
}

main().catch(async (err) => {
  console.error(err);
  await closePool();
  process.exitCode = 1;
});
